SELECT 
FROM pjt_i18n_messages m
JOIN pjt_i18n_message_groups g ON g.id = m.group_id
WHERE m.group_id = #{groupId}
  AND m.code = #{code}

SELECT EXISTS(
    SELECT 1 FROM pjt_i18n_messages
    WHERE group_id = #{groupId} AND code = #{code}
)

mapper.update:
UPDATE pjt_i18n_messages
SET group_id = #{groupId},
    code = #{code},
    description = #{description}
WHERE id = #{id}
